    response: SharedHttpApiSchemasOutcome;
    error: SharedHttpApiResponses400Response | SharedHttpApiResponses401Response | SharedHttpApiResponses403Response | SharedHttpApiSchemasRejectedOutcome | SharedHttpApiResponses409Response | SharedHttpApiResponses422Response | SharedHttpApiResponses428Response | SharedHttpApiResponses503Response;
